article("30", "Deze wet kan worden aangehaald als \"Leerplichtwet 1969\". Zij treedt in werking op 1 januari 1969.").
article_property("30", "url", "https://wetten.overheid.nl/BWBR0002628/2026-08-01#Artikel30").

ee_literal("leerplichtwet_1969@2026-08-01/expression1/1", true).
